pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address caller, uint256 amount) public {
        address receiver = address(0x1234);

        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(amount > 0);

        vm.deal(address(c), amount);

        bool ok;
        vm.prank(caller);
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller == address(this)) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}
